class ModelNew(torch.nn.Module):
    """
    Optimized model: keep Linear for GEMM and fuse swish/divide/clamp/tanh/clamp into a single AscendC custom op.
    """
    def __init__(self, in_features, out_features, bias=True):
        super(ModelNew, self).__init__()
        self.gemm = torch.nn.Linear(in_features, out_features, bias=bias)

    def forward(self, x):
        x = self.gemm(x)  # GEMM (matmul + bias)
        # Fused post-ops: swish -> divide -> clamp -> tanh -> clamp
        x = custom_ops_lib.gemm_swish_divide_clamp_tanh_clamp_custom(x)
